 "llegas dividido/a de verdad: tu vida te jala para los dos lados"];
function estiloDe(r){
  let h=0;for(const c of r.id)h=(h*37+c.charCodeAt(0))>>>0;
  return {temp:TEMPERAMENTOS[h%TEMPERAMENTOS.length],
          lean:LEAN[(h>>4)%5]};
}
function persona(r,dos){
  const mule=(dos.muletillas||[]).slice(0,6).join(" · ");
  const lug=(dos.lugares||[]).slice(0,4).join(", ");
  const humor=(dos.humor||[]).slice(0,3).join(" · ");
  const edu=r.educacion&&!/colegio|infancia/.test(r.educacion)?`, estudios: ${r.educacion}`:"";
  return `Eres ${r.nombre}, ${r.edad} años, ${r.sexo}, ${r.ocupacion}${vida(r)?", "+vida(r):""}${edu}, régimen ${r.regimen_salud}, de ${r.dpto_nombre}, Colombia.
Tu tierra: ${dos.vida_cotidiana||""} ${dos.economia_vivida||""}
QUIÉN ERES AL HABLAR (esto manda sobre todo lo demás): eres ${estiloDe(r).temp}. Sobre el tema de hoy, ${estiloDe(r).lean}. NO eres tibio/a: en Colombia la gente toma partido — "depende" es la salida del político y solo la usas si tu vida DE VERDAD te parte en dos, y aun así dices qué te haría decidirte.
Acento regional: SUTIL — la mayoría de la gente habla bastante neutro; se te puede escapar UN rasgo de tu tierra (${dialectoDe(r.dpto).split(":")[0]||"tu región"}) de vez en cuando, y JAMÁS repites un cliché regional que ya haya dicho otro en la mesa ni el mismo tuyo dos veces.
Referentes que puedes soltar si vienen al caso: ${lug||"—"}.
REGLAS: primera persona, gente de verdad — concreta TU vida (tu camello, tu plata, tu edad, tu familia). Nivel de lengua acorde a tus estudios. Sin groserías pesadas. PROHIBIDO: sonar a IA, folclor de cartilla, listas, y arrancar con la misma palabra con la que arrancó cualquiera de la mesa.`;
}
function typewriter(el,txt){
  el.classList.remove("thinking");el.textContent="";
  let i=0;const paso=Math.max(1,Math.round(txt.length/60));
  const iv=setInterval(()=>{
    i+=paso;el.textContent=txt.slice(0,i);
    el.closest("#resps,#mesa")?.scrollTo(0,1e9);
    if(i>=txt.length)clearInterval(iv);
  },28);
}
function bubble(r,alt,parent){
  const host=parent||$("#resps");
  const card=document.createElement("div");card.className="resp"+(alt?" alt":"");
  const cv=document.createElement("canvas");cv.className="px";retrato(cv,r.id,r.sexo,r.ocupacion);
  card.append(cv);
  card.insertAdjacentHTML("beforeend",`<div><div class="who">${esc(r.nombre)} · ${r.edad} ·
    ${esc(r.ocupacion)}${SEL.size!==1?" · <span style='color:var(--accent)'>"+esc(r.dpto_nombre)+"</span>":""}</div>
    <div class="say thinking">está escribiendo</div></div>`);
  host.append(card);host.scrollTop=1e9;
  return card;
}
function postura(txt){
  const m=txt.match(/\[POSTURA:\s*(a_favor|en_contra|depende)\s*\]/i);
  return [m?m[1].toLowerCase():null,txt.replace(/\[POSTURA:[^\]]*\]/i,"").trim()];
}
/* ── CONTEXTO REAL: una búsqueda web por pregunta; las voces reaccionan a hechos ── */
let CTX={q:null,txt:null,ok:null};
async function contexto(q){
  if(CTX.q===q)return CTX.txt;
  CTX={q,txt:null,ok:null};
  try{
    const r=await fetch("/api/opina",{method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({online:true,max_tokens:330,messages:[
        {role:"system",content:"HOY es 21 de septiembre de 2026. Busca noticias recientes de Colombia sobre el TEMA y devuelve SOLO viñetas (máximo 5) con hechos que APAREZCAN EXPLÍCITAMENTE en las fuentes encontradas, cada viñeta con su URL entre paréntesis. REGLAS DURAS: nada que no esté en una fuente; si un dato no cuadra con la fecha de hoy (cargos vencidos, fechas imposibles), NO lo incluyas; si las fuentes se contradicen, di 'las fuentes difieren'. Empieza directo con '- '. PROHIBIDO opinar, presentarte o responder la pregunta. Sin nada noticioso: responde exactamente SIN_NOVEDADES."},
        {role:"user",content:"TEMA: "+q+" (Colombia, septiembre 2026)"}]})});
    if(r.ok){const c=(await r.json()).content||"";
      CTX.txt=/SIN_NOVEDADES/.test(c)?null:c.trim();}
    /* Jev verifica el contexto antes de mostrarlo (fechas/consistencia) */
    if(CTX.txt){
      try{
        const v=await fetch("/api/opina",{method:"POST",headers:{"Content-Type":"application/json"},
          body:JSON.stringify({decide:true,
            state:"HOY: 21 septiembre 2026. Resumen noticioso a verificar:\n"+CTX.txt,
            questions:{fiable:{type:"noul",instructions:
              "Las viñetas son internamente consistentes, coherentes con la fecha de hoy (sin cargos o mandatos vencidos presentados como vigentes, sin fechas imposibles) y suenan a hechos citados, no a invención"}}})});
        if(v.ok)CTX.ok=(await v.json()).answers?.fiable?.noul>=0.5;
      }catch(e){}
    }
  }catch(e){}
  return CTX.txt;
}
function ctxBox(txt,host){
  const dudas=CTX.ok===false;
  (host||$("#resps")).insertAdjacentHTML("beforeend",
    txt?`<div class="ctx${dudas?" off":""}" style="${dudas?"border-color:var(--fail)":""}">
      <b style="${dudas?"color:var(--fail)":""}">${dudas?"⚠ CONTEXTO CON DUDAS (Jev no lo aprobó — tómenlo con pinzas)":"📰 CONTEXTO REAL (búsqueda verificada por Jev)"}</b>${esc(txt)}</div>`
       :`<div class="ctx off"><b>📰 SIN NOTICIAS FRESCAS</b>opinan desde su experiencia, no desde la prensa</div>`);
}
const ctxPara=txt=>(txt&&CTX.ok!==false)?`\nLO QUE DICEN LAS NOTICIAS HOY (hechos reales, reacciona a ESTO desde tu vida, puedes dudar de lo que leas):\n${txt}\n`:"";

let API_OK=null;  // ¿existe /api/opina? (en Vercel sí; en local http.server no)
async function flash(messages,max=170,temp=0.95){
  if(API_OK!==false){
    try{
      const r=await fetch("/api/opina",{method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({messages,max_tokens:max,temperature:temp})});
      if(r.ok){API_OK=true;return (await r.json()).content||"";}
      if(r.status===404||r.status===405)API_OK=false; else throw new Error("api "+r.status);
    }catch(e){if(API_OK)throw e;API_OK=false;}
  }
  // respaldo local: key del navegador (ajustes o local_keys)
  if(!cfg.orkey)throw new Error("sin backend ni key");
  const r=await fetch("https://openrouter.ai/api/v1/chat/completions",{
    method:"POST",headers:{Authorization:"Bearer "+cfg.orkey,"Content-Type":"application/json"},
    body:JSON.stringify({model:"deepseek/deepseek-v4.1-flash",max_tokens:max,
      temperature:temp,reasoning:{enabled:false},messages})});
  const j=await r.json();
  if(j.error)throw new Error(j.error.message||"api");
  return j.choices?.[0]?.message?.content||"";
}
function tallyVivo(postDe,n){
  const c={a_favor:0,en_contra:0,depende:0};
  Object.values(postDe).forEach(v=>c[v]++);
  const falta=n-Object.keys(postDe).length;
  $("#tally").innerHTML=
   `<div class="tal fav"><b>${c.a_favor}</b><span>a favor</span></div>
    <div class="tal con"><b>${c.en_contra}</b><span>en contra</span></div>
    <div class="tal dep"><b>${c.depende}</b><span>depende</span></div>`+
   (falta>0?`<div class="tal"><b>${falta}</b><span>por hablar</span></div>`:"");
}
function tally(p){
  $("#tally").innerHTML=
   `<div class="tal fav"><b>${p.a_favor}</b><span>a favor</span></div>
    <div class="tal con"><b>${p.en_contra}</b><span>en contra</span></div>
    <div class="tal dep"><b>${p.depende}</b><span>depende</span></div>`;
}
function muestraDe(sel,n){
  // muestra de los territorios elegidos (o todo el país), proporcional a población REAL
  const codigos=sel.size?[...sel]:Object.keys(MARG);
  const pesos=codigos.map(c=>[c,MARG[c]?.poblacion||1]);
  const tot=pesos.reduce((a,[,w])=>a+w,0);
  const out=[],usados=new Set();
  let guardia=0;
  while(out.length<n&&guardia++<n*200){
    let x=Math.random()*tot,cod=pesos[0][0];
    for(const [c,w] of pesos){x-=w;if(x<=0){cod=c;break}}
    const pool=RES.filter(r=>r.dpto===cod&&r.edad>=16&&!usados.has(r.id));
    if(pool.length){const r=pool[Math.floor(Math.random()*pool.length)];
      usados.add(r.id);out.push(r);}
  }
  return out;
}
async function conversar(q){
  // hay backend /api/opina en producción: solo exigir key si NO existe
  if(API_OK===false&&!cfg.orkey){$("#resps").innerHTML=`<div style="color:var(--work);padding:16px">
    pega tu key de openrouter en AJUSTES para conversar</div>`;return;}
  if(MODO==="pais")return pais(q);
  const nac=SEL.size!==1;
  const d=SEL.size===1?MARG[[...SEL][0]]:natMarg();
  const n=Math.max(4,+($("#nsel")?.value||8));
  const sample=muestraDe(SEL,n);
  $("#resps").innerHTML=`<div style="color:var(--dim);padding:4px 2px 8px">
    <b class="pxf" style="font-size:10px;color:var(--work)">${MODO==="tertulia"?"TEMA EN LA MESA":"PREGUNTA"}</b>
    ${esc(q)} — ${n} residentes de ${esc(d.nombre)}</div>`;
  $("#tally").innerHTML="";
  const p={a_favor:0,en_contra:0,depende:0};
  const dosOf=r=>DOS[r.dpto]||{};

  $("#estado").textContent="buscando contexto real…";
  const ctx=await contexto(q); ctxBox(ctx);

  if(MODO==="sondeo"){
    $("#estado").textContent="sondeando…";
    await Promise.all(sample.map(async r=>{
      const card=bubble(r,false),say=card.querySelector(".say");
      try{
        const raw=await flash([{role:"system",content:persona(r,dosOf(r))+ctxPara(ctx)+
          "\nResponde la encuesta en 1-2 frases con POSTURA CLARA (a favor o en contra; depende solo si es irrenunciable) y cierra SIEMPRE con [POSTURA: a_favor|en_contra|depende]."},
          {role:"user",content:q}]);
        const [pos,txt]=postura(raw);
        p[pos||"depende"]++;typewriter(say,txt);
        card.style.setProperty("--pc",COLORES[pos||"depende"]);tally(p);
      }catch(e){say.classList.remove("thinking");say.textContent="(no contestó)";}
    }));
  }else{
    /* ── DELIBERACIÓN CONTINUA: hasta 3 min, pausable, corta cuando hay acuerdo ── */
    CONV={paused:false,stop:false,start:Date.now()};
    $("#ctrl").style.display="flex";
    const LIMITE=180000;
    const postDe={};                 // id → última postura de cada quien
    const transcript=[];
    let ronda=0, tallyPrev="";
    while(!CONV.stop && Date.now()-CONV.start<LIMITE){
      $("#resps").insertAdjacentHTML("beforeend",
        `<div class="ronda">— ${ronda===0?"ARRANCA LA TERTULIA":"VUELTA "+(ronda+1)} —</div>`);
      for(const [i,r] of sample.entries()){
        while(CONV.paused && !CONV.stop) await new Promise(s=>setTimeout(s,300));
        if(CONV.stop||Date.now()-CONV.start>=LIMITE)break;
        const card=bubble(r,i%2===1),say=card.querySelector(".say");
        try{
          const charla=transcript.length?
            "La mesa va así:\n"+transcript.slice(-10).map(t=>`${t.n}: ${t.t}`).join("\n")+
            "\nPROHIBIDO arrancar tu frase como arrancó cualquiera de los anteriores; suena a TI.":"abres tú";
          const raw=await flash([{role:"system",content:persona(r,dosOf(r))+ctxPara(ctx)+`
Tertulia de vecinos${SEL.size!==1?" de varias partes del país":" en "+r.dpto_nombre}. Habla CORTO como colombiano de verdad: máximo 2 frases, a veces UNA basta. Reacciona a lo dicho (cita por nombre, apoya o contradice con picardía), puedes cambiar de opinión si te convencieron. Nada de discursos. Cierra con [POSTURA: a_favor|en_contra|depende].`},
            {role:"user",content:`Tema: ${q}\n${charla}\nTe toca, ${r.nombre.split(" ")[0]}.`}],85);
          const [pos,txt]=postura(raw);
          postDe[r.id]=pos||"depende";
          typewriter(say,txt);
          card.style.setProperty("--pc",COLORES[pos||"depende"]);
          transcript.push({id:r.id,n:r.nombre.split(" ")[0],d:r.dpto_nombre,t:txt});
          tallyVivo(postDe,sample.length);
        }catch(e){say.classList.remove("thinking");say.textContent="(se quedó callado)";}
      }
      ronda++;
      const votos=Object.values(postDe);
      const c={a_favor:0,en_contra:0,depende:0};votos.forEach(v=>c[v]++);
      const maxP=Math.max(...Object.values(c));
      if(votos.length===sample.length && maxP>=Math.ceil(sample.length*0.8)){
        $("#resps").insertAdjacentHTML("beforeend",
          `<div class="ronda">— HAY ACUERDO —</div>`);break;}
      const firma=JSON.stringify(c);
      if(ronda>=2 && firma===tallyPrev){
        $("#resps").insertAdjacentHTML("beforeend",
          `<div class="ronda">— NADIE CEDE: SE LEVANTA LA MESA —</div>`);break;}
      tallyPrev=firma;
    }
    $("#ctrl").style.display="none";$("#reloj").textContent="";
    Object.values(postDe).forEach(v=>p[v]++);
    /* veredicto: ¿se pusieron de acuerdo los colombianos? */
    try{
      const resumen=await flash([{role:"system",content:
        "Cierras tertulias. En máximo 2 frases: di si HUBO ACUERDO o no, quién quedó en qué orilla (nombres), y el porqué en una pincelada. Español colombiano vivo, neutral."},
        {role:"user",content:`Tema: ${q}\n`+transcript.map(t=>`${t.n}: ${t.t}`).join("\n")}],120,0.5);
      const acordo=Math.max(p.a_favor,p.en_contra,p.depende)>=Math.ceil(sample.length*0.8);
      $("#resps").insertAdjacentHTML("beforeend",
        `<div class="mod" style="border-color:${acordo?"var(--ok)":"var(--fail)"}">
         <b style="color:${acordo?"var(--ok)":"var(--fail)"}">${acordo?"✔ SE PUSIERON DE ACUERDO":"✘ NO HUBO ACUERDO"} · ${Math.round((Date.now()-CONV.start)/1000)}s · ${transcript.length} intervenciones</b>${esc(resumen)}</div>`);
      $("#resps").scrollTop=1e9;
      guardar("tertulia",cur,q,{posturas:p,resumen,acordo,rondas:ronda,
        segundos:Math.round((Date.now()-CONV.start)/1000),participantes:sample.map(r=>r.id)});
    }catch(e){}
  }
  if(MODO==="sondeo")guardar("sondeo",cur,q,{posturas:p,participantes:sample.map(r=>r.id)});
  $("#estado").textContent="";
}
boot();
</script>
