          {role:"user",content:q}]);
        const [pos,txt]=postura(raw);
        p[pos||"depende"]++;typewriter(say,txt);
        card.style.setProperty("--pc",COLORES[pos||"depende"]);tally(p);
      }catch(e){say.classList.remove("thinking");say.textContent="(no contestó)";}
    }));
  }else{
    /* ── DELIBERACIÓN CONTINUA: hasta 3 min, pausable, corta cuando hay acuerdo ── */
    CONV={paused:false,stop:false,start:Date.now()};
    $("#ctrl").style.display="flex";
    const LIMITE=180000;
    const postDe={};                 // id → última postura de cada quien
    const transcript=[];
    let ronda=0, tallyPrev="";
    while(!CONV.stop && Date.now()-CONV.start<LIMITE){
      $("#resps").insertAdjacentHTML("beforeend",
        `<div class="ronda">— ${ronda===0?"ARRANCA LA TERTULIA":"VUELTA "+(ronda+1)} —</div>`);
      for(const [i,r] of sample.entries()){
        while(CONV.paused && !CONV.stop) await new Promise(s=>setTimeout(s,300));
        if(CONV.stop||Date.now()-CONV.start>=LIMITE)break;
        const card=bubble(r,i%2===1),say=card.querySelector(".say");
        try{
          const charla=transcript.length?
            "La mesa va así:\n"+transcript.slice(-10).map(t=>`${t.n}: ${t.t}`).join("\n")+
            "\nPROHIBIDO arrancar tu frase como arrancó cualquiera de los anteriores; suena a TI.":"abres tú";
          const raw=await flash([{role:"system",content:persona(r,dosOf(r))+ctxPara(ctx)+`
Tertulia de vecinos${SEL.size!==1?" de varias partes del país":" en "+r.dpto_nombre}. Habla CORTO como colombiano de verdad: máximo 2 frases, a veces UNA basta. Reacciona a lo dicho (cita por nombre, apoya o contradice con picardía), puedes cambiar de opinión si te convencieron. Nada de discursos. Cierra con [POSTURA: a_favor|en_contra|depende].`},
            {role:"user",content:`Tema: ${q}\n${charla}\nTe toca, ${r.nombre.split(" ")[0]}.`}],85);
          const [pos,txt]=postura(raw);
          postDe[r.id]=pos||"depende";
          typewriter(say,txt);
          card.style.setProperty("--pc",COLORES[pos||"depende"]);
          transcript.push({id:r.id,n:r.nombre.split(" ")[0],d:r.dpto_nombre,t:txt});
          tallyVivo(postDe,sample.length);
        }catch(e){say.classList.remove("thinking");say.textContent="(se quedó callado)";}
      }
      ronda++;
      const votos=Object.values(postDe);
      const c={a_favor:0,en_contra:0,depende:0};votos.forEach(v=>c[v]++);
      const maxP=Math.max(...Object.values(c));
      if(votos.length===sample.length && maxP>=Math.ceil(sample.length*0.8)){
        $("#resps").insertAdjacentHTML("beforeend",
          `<div class="ronda">— HAY ACUERDO —</div>`);break;}
      const firma=JSON.stringify(c);
      if(ronda>=2 && firma===tallyPrev){
        $("#resps").insertAdjacentHTML("beforeend",
          `<div class="ronda">— NADIE CEDE: SE LEVANTA LA MESA —</div>`);break;}
      tallyPrev=firma;
    }
    $("#ctrl").style.display="none";$("#reloj").textContent="";
    Object.values(postDe).forEach(v=>p[v]++);
    /* veredicto: ¿se pusieron de acuerdo los colombianos? */
    try{
      const resumen=await flash([{role:"system",content:
        "Cierras tertulias. En máximo 2 frases: di si HUBO ACUERDO o no, quién quedó en qué orilla (nombres), y el porqué en una pincelada. Español colombiano vivo, neutral."},
        {role:"user",content:`Tema: ${q}\n`+transcript.map(t=>`${t.n}: ${t.t}`).join("\n")}],120,0.5);
      const acordo=Math.max(p.a_favor,p.en_contra,p.depende)>=Math.ceil(sample.length*0.8);
      $("#resps").insertAdjacentHTML("beforeend",
        `<div class="mod" style="border-color:${acordo?"var(--ok)":"var(--fail)"}">
         <b style="color:${acordo?"var(--ok)":"var(--fail)"}">${acordo?"✔ SE PUSIERON DE ACUERDO":"✘ NO HUBO ACUERDO"} · ${Math.round((Date.now()-CONV.start)/1000)}s · ${transcript.length} intervenciones</b>${esc(resumen)}</div>`);
      $("#resps").scrollTop=1e9;
      guardar("tertulia",cur,q,{posturas:p,resumen,acordo,rondas:ronda,
        segundos:Math.round((Date.now()-CONV.start)/1000),participantes:sample.map(r=>r.id)});
    }catch(e){}
  }
  if(MODO==="sondeo")guardar("sondeo",cur,q,{posturas:p,participantes:sample.map(r=>r.id)});
  $("#estado").textContent="";
}
boot();
</script>
</body>
