/* mapa-navegador: el país siempre a la vista, clic = elegir territorio */
#navmap{padding:8px 8px 4px;position:relative}
#navmap svg{width:100%;height:auto;display:block}
#navmap path{fill:var(--panel2);stroke:#2a3350;stroke-width:1.2;cursor:pointer;transition:fill .25s}
#navmap path:hover{stroke:var(--work);stroke-width:2}
#navmap path.sel{stroke:var(--work);stroke-width:2.5;filter:drop-shadow(0 0 4px #ffd23e66)}
#navmap path.fav{fill:color-mix(in srgb,var(--ok) 45%,var(--panel2))}
#navmap path.con{fill:color-mix(in srgb,var(--fail) 45%,var(--panel2))}
#navmap path.dep{fill:color-mix(in srgb,var(--work) 40%,var(--panel2))}
#navmap path.hot{stroke:var(--work);stroke-width:2;animation:blink 1s steps(2) infinite}
#maplabel{font-family:"Silkscreen";font-size:9px;color:var(--work);text-align:center;
padding:5px 0 3px;min-height:20px;letter-spacing:.06em}
#ctrl{display:none;gap:4px}
#ctrl button{font-family:"Silkscreen";font-size:8px;padding:3px 8px}
#ctrl button.pausa{color:var(--work);border-color:var(--work)}
#reloj{font-family:"Silkscreen";font-size:9px;color:var(--faint)}
.acuerdo{flex:1 1 100%;border:2px solid var(--grid);padding:6px 10px}
.acuerdo .t{display:flex;justify-content:space-between;font-size:10.5px;color:var(--dim);margin-bottom:4px}
.acuerdo .t b{font-family:"Silkscreen";font-size:10px;color:var(--text);font-weight:400}
.acuerdo .g{height:10px;background:var(--panel2);border:1px solid var(--grid);display:flex}
.acuerdo .g i{height:100%}
h3{font-family:"Silkscreen";font-size:9px;color:var(--faint);margin:12px 0 6px;font-weight:400}
h3:first-child{margin-top:0}
.pyr{display:grid;grid-template-columns:1fr 34px 1fr;gap:2px 6px;font-size:10px}
.pyr .lab{color:var(--faint);text-align:center;font-family:"Silkscreen";font-size:7px;padding-top:1px}
.pyr .bar{position:relative;height:13px;background:var(--panel2);border:1px solid var(--grid)}
.pyr .bar i{position:absolute;top:1px;bottom:1px;opacity:.9}
.pyr .bar.l i{right:0;background:var(--hom)}
.pyr .bar.r i{left:0;background:var(--muj)}
.pyr .bar s{position:absolute;top:-1px;bottom:-1px;width:2px;background:var(--text);opacity:.85}
.leyenda{display:flex;gap:14px;font-size:10px;color:var(--faint);margin-top:6px}
.leyenda i{display:inline-block;width:9px;height:9px;vertical-align:-1px;margin-right:4px}
.hbar{margin:3px 0}
.hbar .t{display:flex;justify-content:space-between;font-size:11.5px;color:var(--dim)}
.hbar .t b{font-family:"Silkscreen";font-size:10px;color:var(--text);font-weight:400}
.hbar .g{height:12px;background:var(--panel2);border:1px solid var(--grid);position:relative}
.hbar .g i{position:absolute;inset:1px auto 1px 1px;background:var(--accent)}
.fuente{font-size:9.5px;color:var(--faint);margin-top:2px}

#encuesta{grid-area:encuesta;display:flex;flex-direction:column;min-height:74vh}
#modo{display:flex;gap:4px}
#modo button{font-family:"Silkscreen";font-size:8px;padding:3px 8px;color:var(--faint)}
#modo button[aria-pressed="true"]{color:var(--work);border-color:var(--work)}
#resps{flex:1;overflow-y:auto;padding:10px;display:flex;flex-direction:column;gap:8px}
.resp{display:grid;grid-template-columns:34px 1fr;gap:8px;background:var(--panel2);
border:2px solid var(--grid);padding:8px;border-left:4px solid var(--pc,var(--grid));
max-width:92%;animation:entra .22s steps(3)}
.resp.alt{margin-left:auto;grid-template-columns:1fr 34px;border-left:2px solid var(--grid);
border-right:4px solid var(--pc,var(--grid))}
.resp.alt .px{order:2}.resp.alt>div{order:1;text-align:right}
@keyframes entra{from{transform:translateY(8px);opacity:0}}
.resp .who{font-family:"Silkscreen";font-size:8px;color:var(--dim);margin-bottom:3px}
.resp .say{font-size:12.5px;line-height:1.45}
.resp .say.thinking{color:var(--faint)}
.resp .say.thinking::after{content:"···";animation:blink .8s steps(2) infinite;
font-family:"Silkscreen";letter-spacing:2px}
.resp .px{width:28px;height:28px;image-rendering:pixelated}
.ctx{border:2px solid var(--accent);border-left-width:5px;background:var(--panel2);
padding:8px 12px;font-size:12px;line-height:1.55;color:var(--dim);white-space:pre-wrap}
.ctx b{font-family:"Silkscreen";font-size:8px;color:var(--accent);display:block;margin-bottom:4px}
.ctx.off{border-color:var(--grid);opacity:.85}
.mod{border:2px solid var(--accent);background:var(--panel2);padding:9px 12px;
font-size:12.5px;line-height:1.5;color:var(--dim)}
.mod b{font-family:"Silkscreen";font-size:8px;color:var(--accent);display:block;margin-bottom:4px}
/* mapa del país */
#mapa{display:grid;grid-template-columns:minmax(240px,340px) 1fr;gap:10px;min-height:0}
#mapa svg{width:100%;height:auto;max-height:66vh}
#mapa path{fill:var(--panel2);stroke:var(--grid);stroke-width:1;cursor:pointer;
transition:fill .25s}
#mapa path:hover{stroke:var(--work);stroke-width:1.5}
#mapa path.hot{stroke:var(--work);stroke-width:2;animation:blink 1s steps(2) infinite}
#mapa path.fav{fill:color-mix(in srgb,var(--ok) 45%,var(--panel2))}
#mapa path.con{fill:color-mix(in srgb,var(--fail) 45%,var(--panel2))}
#mapa path.dep{fill:color-mix(in srgb,var(--work) 40%,var(--panel2))}
#mesa{display:flex;flex-direction:column;gap:8px;overflow-y:auto;max-height:66vh;min-width:0}
#mesa .hint{color:var(--faint);padding:14px;text-align:center}
.conclu{border:2px solid var(--pc,var(--accent));background:var(--panel2);padding:9px 12px;
font-size:12.5px;line-height:1.5}
.conclu b{font-family:"Silkscreen";font-size:8px;display:block;margin-bottom:4px;color:var(--pc,var(--accent))}
.ronda{font-family:"Silkscreen";font-size:8px;color:var(--faint);text-align:center;
padding:4px 0;letter-spacing:.2em}
@keyframes blink{50%{opacity:.3}}
#tally{display:flex;gap:8px;padding:8px 10px;border-top:var(--px) solid var(--grid);flex-wrap:wrap}
.tal{flex:1;min-width:110px;border:2px solid var(--grid);padding:6px 9px;text-align:center}
.tal b{font-family:"Silkscreen";font-size:14px;display:block;font-weight:400}
.tal span{font-size:10px;color:var(--faint)}
.tal.fav{border-color:var(--ok)} .tal.fav b{color:var(--ok)}
.tal.con{border-color:var(--fail)} .tal.con b{color:var(--fail)}
.tal.dep{border-color:var(--work)} .tal.dep b{color:var(--work)}
#qbar{display:flex;gap:6px;padding:10px;border-top:var(--px) solid var(--grid)}
#qin{flex:1}
#modohelp{font-size:11px;color:var(--work);padding:7px 10px 0;letter-spacing:.02em}
#selinfo{font-size:11.5px;color:var(--dim);padding:4px 10px 6px;border-bottom:2px solid var(--grid)}
#selinfo b{font-family:"Silkscreen";font-size:8px;color:var(--faint)}
#selinfo .chip{display:inline-block;border:1px solid var(--work);color:var(--work);
padding:1px 4px 1px 8px;margin:1px 3px}
#selinfo .chip i{cursor:pointer;font-style:normal;padding:0 4px;color:var(--dim)}
#selinfo .chip i:hover{color:var(--fail)}
#selinfo button{font-size:10px;padding:1px 7px;margin-left:6px;color:var(--dim)}
#sugg{display:flex;flex-wrap:wrap;gap:4px;padding:0 10px 10px}
#sugg button{font-size:10.5px;padding:2px 8px;color:var(--dim)}
#sugg button:hover{color:var(--work);border-color:var(--work)}

#ficha{grid-area:ficha;display:flex;flex-direction:column;gap:8px}
#ficha .body{padding:10px;font-size:12px;line-height:1.5;color:var(--dim)}
#ficha .body b{color:var(--text);font-weight:500}
#ficha .tag{display:inline-block;border:1px solid var(--grid);padding:1px 7px;
margin:2px 3px 2px 0;font-size:10.5px;color:var(--dim)}
#muestra{display:grid;grid-template-columns:1fr 1fr;gap:4px;padding:8px}
.res{display:flex;gap:6px;align-items:center;background:var(--panel2);
border:1px solid var(--grid);padding:4px 6px;font-size:10.5px;color:var(--dim)}
.res canvas{width:20px;height:20px;image-rendering:pixelated}

#banner{grid-area:banner;text-align:center;font-size:10.5px;color:var(--faint);
padding:6px;border:1px dashed var(--grid)}
@media(max-width:1000px){#app{grid-template-columns:1fr;
grid-template-areas:"top" "encuesta" "censo" "ficha" "banner"}#kpis{display:none}}
</style>
</head>
<body>
<div id="app">
  <header id="top">
    <span id="title">SIM<small>▸</small>COLOMBIA</span>
    <select id="dptosel" aria-label="Departamento"></select>
    <a class="back" href="../">◂ visor del enjambre</a>
    <div id="kpis"></div>
    <button id="gear" class="pxbtn">AJUSTES</button>
  </header>

  <section id="censo">
    <div class="panel"><h2>colombia <b id="maptag">toca un territorio</b></h2>
      <div id="navmap"></div><div id="maplabel">—</div>
    </div>
    <div class="panel" style="flex:1"><h2>el censo <b id="c-src-tag">DANE</b></h2>
      <div class="body" id="censobody"></div>
    </div>
  </section>

  <section id="encuesta" class="panel">
    <h2><span>la conversación <b id="estado"></b> <span id="reloj"></span></span>
      <span id="ctrl"><button id="btnpausa" type="button">⏸ PAUSAR</button><button id="btnfin" type="button">■ CERRAR</button></span>
      <span id="modo"><button data-m="pais" aria-pressed="false">PAÍS</button><button data-m="tertulia" aria-pressed="true">TERTULIA</button><button data-m="sondeo" aria-pressed="false">SONDEO</button></span></h2>
    <div id="modohelp"></div>
    <div id="selinfo"></div>
    <div id="resps"><div style="color:var(--faint);padding:16px;text-align:center;line-height:2">
      <b style="color:var(--work)">1.</b> toca territorios en el mapa (uno, varios, o ninguno = todo el país)<br>
      <b style="color:var(--work)">2.</b> elige el tipo de conversación arriba a la derecha<br>
      <b style="color:var(--work)">3.</b> suelta tu pregunta abajo — y míralos hablar</div></div>
    <div id="tally"></div>
    <div id="sugg"></div>
    <form id="qbar">
      <input id="qin" placeholder="pregúntale al país lo que quieras… (toca una sugerencia y edítala)" autocomplete="off" style="font-size:13.5px;padding:8px 11px">
      <select id="nsel" aria-label="Tamaño del panel" style="flex:0 0 auto">
        <option value="8">8 voces</option><option value="12">12 voces</option>
        <option value="20">20 voces</option>
      </select>
      <button class="pxbtn" type="submit">PREGUNTAR</button>
    </form>
  </section>

  <aside id="ficha">
    <div class="panel"><h2>la tierra</h2><div class="body" id="dossier"></div></div>
    <div class="panel"><h2>residentes de muestra</h2><div id="muestra"></div></div>
  </aside>

  <div id="banner">⚠ SIMULACIÓN — residentes sintéticos generados de marginales reales
  (DANE / datos.gov.co). Las opiniones son de personajes verosímiles, no de personas.
  Reporte de fidelidad: <a href="validacion.json" style="color:var(--dim)">validacion.json</a></div>
</div>

<div id="cfg" style="position:fixed;top:56px;right:8px;width:290px;z-index:9;display:none;
background:var(--panel);border:var(--px) solid var(--grid);padding:14px;box-shadow:6px 6px 0 #000a">
  <label style="font-family:Silkscreen;font-size:8px;color:var(--faint)">openrouter key (encuesta)</label>
  <input id="c-orkey" style="width:100%" placeholder="sk-or-v1-…">
</div>

<script>
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let cfg={orkey:""};
try{cfg={...cfg,...JSON.parse(localStorage.getItem("sim-cfg")||"{}")};
  if(!cfg.orkey){const ag=JSON.parse(localStorage.getItem("ag-cfg")||"{}");if(ag.orkey)cfg.orkey=ag.orkey;}}catch(e){}
// clave local (solo existe en la máquina de Daniel; gitignoreada)
if(!cfg.orkey)fetch("../assets/local_keys.json").then(r=>r.json())
  .then(d=>{if(d.openrouter)cfg.orkey=d.openrouter}).catch(()=>{});
$("#gear").onclick=e=>{e.stopPropagation();const c=$("#cfg");c.style.display=c.style.display==="none"?"block":"none"};
document.addEventListener("click",e=>{if(!$("#cfg").contains(e.target)&&e.target.id!=="gear")$("#cfg").style.display="none"});
$("#c-orkey").onchange=e=>{cfg.orkey=e.target.value.trim();try{localStorage.setItem("sim-cfg",JSON.stringify(cfg))}catch(_){}};

/* controles de la deliberación */
let CONV={paused:false,stop:false,start:0};
$("#btnpausa").onclick=()=>{CONV.paused=!CONV.paused;
  $("#btnpausa").textContent=CONV.paused?"▶ SEGUIR":"⏸ PAUSAR";
  $("#btnpausa").classList.toggle("pausa",CONV.paused);};
$("#btnfin").onclick=()=>{CONV.stop=true;CONV.paused=false;};
setInterval(()=>{if($("#ctrl").style.display!=="none"&&CONV.start){
  const s=Math.round((Date.now()-CONV.start)/1000);
  $("#reloj").textContent=(CONV.paused?"⏸ ":"")+Math.floor(s/60)+":"+String(s%60).padStart(2,"0");
}},1000);

/* ═══ MODO PAÍS: una pregunta, 33 mesas — el mapa se pinta con las conclusiones ═══ */
let GEO=null,PAIS={q:null,cache:{},tally:{a_favor:0,en_contra:0,depende:0}};
async function pais(q){
  if(!GEO){try{GEO=await fetch("colombia.json").then(r=>r.json())}catch(e){
    $("#resps").innerHTML="<div class='hint'>no cargó el mapa</div>";return;}}
  PAIS={q,cache:{},tally:{a_favor:0,en_contra:0,depende:0}};
  DECIDIDO={}; paintNav();
  $("#tally").innerHTML="";
  $("#maptag").textContent="el país responde";
  $("#resps").innerHTML=`
    <div style="color:var(--dim);padding:2px 2px 8px">
      <b class="pxf" style="font-size:10px;color:var(--work)">EL PAÍS RESPONDE</b> ${esc(q)}</div>
    <div id="mesa"><div class="hint">◂ toca un departamento en el mapa<br><br>
      cada territorio arma su mesa de 4, conversa corto y CONCLUYE —
      el mapa se va pintando con los veredictos</div></div>`;
}
async function mesa(cod){
  const el=$("#mesa"),d=MARG[cod],dos=DOS[cod]||{};
  if(!el)return;
  PAIS.busy??={}; if(PAIS.busy[cod])return; PAIS.busy[cod]=true;
  const path=$(`#navmap path[data-cod="${cod}"]`);
  if(PAIS.cache[cod]){el.innerHTML=PAIS.cache[cod];return;}
  el.innerHTML=`<div class="ronda">— MESA DE ${esc(d.nombre).toUpperCase()} —</div>`;
  path?.classList.add("hot");
  const ctx=await contexto(PAIS.q); ctxBox(ctx,el);
  const sample=RES.filter(r=>r.dpto===cod&&r.edad>=16).sort(()=>Math.random()-.5).slice(0,4);
  const transcript=[];
  for(let i=0;i<sample.length;i++){
    const r=sample[i],card=bubble(r,i%2===1,el),say=card.querySelector(".say");
    try{
      const charla=transcript.length?
        "La mesa va así:\n"+transcript.map(t=>`${t.n}: ${t.t}`).join("\n"):"abres tú la mesa";
      const raw=await flash([{role:"system",content:persona(r,dos)+ctxPara(ctx)+`
Mesa de vecinos en ${d.nombre}. El tema es cómo les afecta A USTEDES, en SU territorio. Reacciona a lo dicho (cita por nombre, contradice o apoya), aterriza con tu vida y tu región. 1-2 frases. Cierra con [POSTURA: a_favor|en_contra|depende].`},
        {role:"user",content:`Tema: ${PAIS.q}\n${charla}\nHabla, ${r.nombre.split(" ")[0]}.`}],160);
      const [pos,txt]=postura(raw);
      typewriter(say,txt);
      card.style.setProperty("--pc",COLORES[pos||"depende"]);
      transcript.push({n:r.nombre.split(" ")[0],t:txt,p:pos||"depende"});
    }catch(e){say.classList.remove("thinking");say.textContent="(se quedó callado)";}
  }
  /* la mesa CONCLUYE — nada de conversación eterna */
  let concl="",pos="depende";
  try{
    const raw=await flash([{role:"system",content:
      `Cierras mesas de conversación. Resume EN QUÉ QUEDÓ esta mesa de ${d.nombre} en 2 frases máximo, con nombres, y da el veredicto del grupo. Cierra con [POSTURA: a_favor|en_contra|depende] (la mayoritaria).`},
      {role:"user",content:`Tema: ${PAIS.q}\n`+transcript.map(t=>`${t.n} (${t.p}): ${t.t}`).join("\n")}],130,0.5);
    [pos,concl]=[postura(raw)[0]||mayoria(transcript),postura(raw)[1]];
  }catch(e){pos=mayoria(transcript);concl="La mesa quedó dividida.";}
  el.insertAdjacentHTML("beforeend",
    `<div class="conclu" style="--pc:${COLORES[pos]}"><b>EN QUÉ QUEDÓ ${esc(d.nombre).toUpperCase()}</b>${esc(concl)}</div>`);
  el.scrollTop=1e9;
  path?.classList.remove("hot");
  path?.classList.add({a_favor:"fav",en_contra:"con",depende:"dep"}[pos]);
  DECIDIDO[cod]=pos; paintNav();
  PAIS.tally[pos]++;
  guardar("pais",cod,PAIS.q,{postura:pos,conclusion:concl,
    participantes:sample.map(r=>r.id),intervenciones:transcript.length});
  $("#tally").innerHTML=
    `<div class="tal fav"><b>${PAIS.tally.a_favor}</b><span>dptos a favor</span></div>
     <div class="tal con"><b>${PAIS.tally.en_contra}</b><span>dptos en contra</span></div>
     <div class="tal dep"><b>${PAIS.tally.depende}</b><span>dptos divididos</span></div>`;
  PAIS.cache[cod]=el.innerHTML;
  PAIS.busy[cod]=false;
}
function mayoria(ts){
  const c={a_favor:0,en_contra:0,depende:0};ts.forEach(t=>c[t.p]++);
  return Object.entries(c).sort((a,b)=>b[1]-a[1])[0][0];
}
/* cada encuesta queda en la base (Supabase) — la memoria del país sintético */
function guardar(modo,dpto,pregunta,resultado){
  try{fetch("https://pwcvskguqyhbhlwnsmmy.supabase.co/rest/v1/sim_encuestas",{
    method:"POST",headers:{apikey:"sb_publishable_1S4AdKr4TJqGWt9LNL_XaQ_OWrCusLw",
    "Content-Type":"application/json"},
    body:JSON.stringify({modo,dpto,pregunta,resultado})}).catch(()=>{});}catch(e){}
}

let RES=[],MARG={},DOS={},VAL={},cur="11";
let SEL=new Set(["11"]);   // territorios elegidos para la muestra (vacío = todo el país)
let DECIDIDO={};  // cod → postura concluida (pinta ambos mapas)

const MODOTXT={
  sondeo:"SONDEO · Todos contestan a la vez. Rápido: cuántos dirían sí, no o depende.",
  tertulia:"TERTULIA · Conversan de a uno, se responden y se contradicen. Hasta 3 minutos o hasta ponerse de acuerdo.",
  pais:"EL PAÍS · Escribes una pregunta y tocas el mapa: cada territorio delibera, concluye y se pinta."};
function selInfo(){
  const el=$("#selinfo"); if(!el)return;
  if(!SEL.size){el.innerHTML=`<b>muestra:</b> toda Colombia (proporcional a población real) — toca el mapa para acotar`;return;}
  el.innerHTML=`<b>muestra:</b> `+[...SEL].map(c=>
    `<span class="chip">${esc(MARG[c]?.nombre||c)}<i data-c="${c}">×</i></span>`).join("")+
    `<button id="cleartodo" type="button">todo el país</button>`;
  el.querySelectorAll("i[data-c]").forEach(i=>i.onclick=()=>{SEL.delete(i.dataset.c);syncSel();});
  const b=el.querySelector("#cleartodo"); if(b)b.onclick=()=>{SEL.clear();syncSel();};
}
function syncSel(){
  if(SEL.size===1)cur=[...SEL][0];
  $("#dptosel").value=SEL.size===1?cur:"CO";
  paintNav();selInfo();render();
}

async function drawNav(){
  if(!GEO){try{GEO=await fetch("colombia.json").then(r=>r.json())}catch(e){return}}
  $("#navmap").innerHTML=`<svg viewBox="${GEO.viewBox}" role="img" aria-label="Mapa de Colombia">${
    Object.entries(GEO.paths).map(([c,p])=>`<path d="${p}" data-cod="${c}"/>`).join("")}</svg>`;
  const svg=$("#navmap svg");
  svg.addEventListener("click",e=>{
    const cod=e.target.dataset?.cod; if(!cod)return;
    if(MODO==="pais"&&PAIS.q){cur=cod;paintNav();render();mesa(cod);return;}
    if(SEL.has(cod)&&SEL.size>0)SEL.delete(cod);else SEL.add(cod);
    cur=cod; syncSel();
  });
  svg.addEventListener("mousemove",e=>{
    const cod=e.target.dataset?.cod;
    $("#maplabel").textContent=cod?
      (MARG[cod]?.nombre||cod)+(DECIDIDO[cod]?" · "+({a_favor:"a favor",en_contra:"en contra",depende:"dividido"})[DECIDIDO[cod]]:""):"—";
  });
  svg.addEventListener("mouseleave",()=>{$("#maplabel").textContent=MARG[cur]?.nombre||"—"});
  paintNav();
}
function paintNav(){
  document.querySelectorAll("#navmap path").forEach(p=>{
    const c=p.dataset.cod;
    p.classList.toggle("sel",SEL.has(c)||(MODO==="pais"&&c===cur));
    p.classList.remove("fav","con","dep");
    if(DECIDIDO[c])p.classList.add({a_favor:"fav",en_contra:"con",depende:"dep"}[DECIDIDO[c]]);
  });
  $("#maptag").textContent=MODO==="pais"?"el país responde":
    SEL.size?SEL.size+" elegido"+(SEL.size>1?"s":""):"toda colombia";
