}
function muestraDe(sel,n){
  // muestra de los territorios elegidos (o todo el país), proporcional a población REAL
  const codigos=sel.size?[...sel]:Object.keys(MARG);
  const pesos=codigos.map(c=>[c,MARG[c]?.poblacion||1]);
  const tot=pesos.reduce((a,[,w])=>a+w,0);
  const out=[],usados=new Set();
  let guardia=0;
  while(out.length<n&&guardia++<n*200){
    let x=Math.random()*tot,cod=pesos[0][0];
    for(const [c,w] of pesos){x-=w;if(x<=0){cod=c;break}}
    const pool=RES.filter(r=>r.dpto===cod&&r.edad>=16&&!usados.has(r.id));
    if(pool.length){const r=pool[Math.floor(Math.random()*pool.length)];
      usados.add(r.id);out.push(r);}
  }
  return out;
}
