let API_OK=null;  // ¿existe /api/opina? (en Vercel sí; en local http.server no)
async function flash(messages,max=170,temp=0.95){
  if(API_OK!==false){
    try{
      const r=await fetch("/api/opina",{method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({messages,max_tokens:max,temperature:temp})});
      if(r.ok){API_OK=true;return (await r.json()).content||"";}
      if(r.status===404||r.status===405)API_OK=false; else throw new Error("api "+r.status);
    }catch(e){if(API_OK)throw e;API_OK=false;}
  }
  // respaldo local: key del navegador (ajustes o local_keys)
  if(!cfg.orkey)throw new Error("sin backend ni key");
  const r=await fetch("https://openrouter.ai/api/v1/chat/completions",{
    method:"POST",headers:{Authorization:"Bearer "+cfg.orkey,"Content-Type":"application/json"},
    body:JSON.stringify({model:"deepseek/deepseek-v4.1-flash",max_tokens:max,
      temperature:temp,reasoning:{enabled:false},messages})});
  const j=await r.json();
  if(j.error)throw new Error(j.error.message||"api");
  return j.choices?.[0]?.message?.content||"";
}
