/* ═══ MODO PAÍS: una pregunta, 33 mesas — el mapa se pinta con las conclusiones ═══ */
let GEO=null,PAIS={q:null,cache:{},tally:{a_favor:0,en_contra:0,depende:0}};
async function pais(q){
  if(!GEO){try{GEO=await fetch("colombia.json").then(r=>r.json())}catch(e){
    $("#resps").innerHTML="<div class='hint'>no cargó el mapa</div>";return;}}
  PAIS={q,cache:{},tally:{a_favor:0,en_contra:0,depende:0}};
  DECIDIDO={}; paintNav();
  $("#tally").innerHTML="";
  $("#maptag").textContent="el país responde";
  $("#resps").innerHTML=`
    <div style="color:var(--dim);padding:2px 2px 8px">
      <b class="pxf" style="font-size:10px;color:var(--work)">EL PAÍS RESPONDE</b> ${esc(q)}</div>
    <div id="mesa"><div class="hint">◂ toca un departamento en el mapa<br><br>
      cada territorio arma su mesa de 4, conversa corto y CONCLUYE —
      el mapa se va pintando con los veredictos</div></div>`;
}
async function mesa(cod){
  const el=$("#mesa"),d=MARG[cod],dos=DOS[cod]||{};
  if(!el)return;
  PAIS.busy??={}; if(PAIS.busy[cod])return; PAIS.busy[cod]=true;
  const path=$(`#navmap path[data-cod="${cod}"]`);
  if(PAIS.cache[cod]){el.innerHTML=PAIS.cache[cod];return;}
  el.innerHTML=`<div class="ronda">— MESA DE ${esc(d.nombre).toUpperCase()} —</div>`;
  path?.classList.add("hot");
  const ctx=await contexto(PAIS.q); ctxBox(ctx,el);
  const sample=RES.filter(r=>r.dpto===cod&&r.edad>=16).sort(()=>Math.random()-.5).slice(0,4);
  const transcript=[];
  for(let i=0;i<sample.length;i++){
    const r=sample[i],card=bubble(r,i%2===1,el),say=card.querySelector(".say");
    try{
      const charla=transcript.length?
        "La mesa va así:\n"+transcript.map(t=>`${t.n}: ${t.t}`).join("\n"):"abres tú la mesa";
      const raw=await flash([{role:"system",content:persona(r,dos)+ctxPara(ctx)+`
Mesa de vecinos en ${d.nombre}. El tema es cómo les afecta A USTEDES, en SU territorio. Reacciona a lo dicho (cita por nombre, contradice o apoya), aterriza con tu vida y tu región. 1-2 frases. Cierra con [POSTURA: a_favor|en_contra|depende].`},
        {role:"user",content:`Tema: ${PAIS.q}\n${charla}\nHabla, ${r.nombre.split(" ")[0]}.`}],160);
      const [pos,txt]=postura(raw);
      typewriter(say,txt);
      card.style.setProperty("--pc",COLORES[pos||"depende"]);
      transcript.push({n:r.nombre.split(" ")[0],t:txt,p:pos||"depende"});
    }catch(e){say.classList.remove("thinking");say.textContent="(se quedó callado)";}
  }
  /* la mesa CONCLUYE — nada de conversación eterna */
  let concl="",pos="depende";
  try{
    const raw=await flash([{role:"system",content:
      `Cierras mesas de conversación. Resume EN QUÉ QUEDÓ esta mesa de ${d.nombre} en 2 frases máximo, con nombres, y da el veredicto del grupo. Cierra con [POSTURA: a_favor|en_contra|depende] (la mayoritaria).`},
      {role:"user",content:`Tema: ${PAIS.q}\n`+transcript.map(t=>`${t.n} (${t.p}): ${t.t}`).join("\n")}],130,0.5);
    [pos,concl]=[postura(raw)[0]||mayoria(transcript),postura(raw)[1]];
  }catch(e){pos=mayoria(transcript);concl="La mesa quedó dividida.";}
  el.insertAdjacentHTML("beforeend",
    `<div class="conclu" style="--pc:${COLORES[pos]}"><b>EN QUÉ QUEDÓ ${esc(d.nombre).toUpperCase()}</b>${esc(concl)}</div>`);
  el.scrollTop=1e9;
  path?.classList.remove("hot");
  path?.classList.add({a_favor:"fav",en_contra:"con",depende:"dep"}[pos]);
  DECIDIDO[cod]=pos; paintNav();
  PAIS.tally[pos]++;
  guardar("pais",cod,PAIS.q,{postura:pos,conclusion:concl,
    participantes:sample.map(r=>r.id),intervenciones:transcript.length});
  $("#tally").innerHTML=
    `<div class="tal fav"><b>${PAIS.tally.a_favor}</b><span>dptos a favor</span></div>
     <div class="tal con"><b>${PAIS.tally.en_contra}</b><span>dptos en contra</span></div>
     <div class="tal dep"><b>${PAIS.tally.depende}</b><span>dptos divididos</span></div>`;
  PAIS.cache[cod]=el.innerHTML;
  PAIS.busy[cod]=false;
}
function mayoria(ts){
  const c={a_favor:0,en_contra:0,depende:0};ts.forEach(t=>c[t.p]++);
  return Object.entries(c).sort((a,b)=>b[1]-a[1])[0][0];
}
/* cada encuesta queda en la base (Supabase) — la memoria del país sintético */
function guardar(modo,dpto,pregunta,resultado){
  try{fetch("https://pwcvskguqyhbhlwnsmmy.supabase.co/rest/v1/sim_encuestas",{
    method:"POST",headers:{apikey:"sb_publishable_1S4AdKr4TJqGWt9LNL_XaQ_OWrCusLw",
    "Content-Type":"application/json"},
    body:JSON.stringify({modo,dpto,pregunta,resultado})}).catch(()=>{});}catch(e){}
}

let RES=[],MARG={},DOS={},VAL={},cur="11";
let SEL=new Set(["11"]);   // territorios elegidos para la muestra (vacío = todo el país)
let DECIDIDO={};  // cod → postura concluida (pinta ambos mapas)

const MODOTXT={
  sondeo:"SONDEO · Todos contestan a la vez. Rápido: cuántos dirían sí, no o depende.",
  tertulia:"TERTULIA · Conversan de a uno, se responden y se contradicen. Hasta 3 minutos o hasta ponerse de acuerdo.",
  pais:"EL PAÍS · Escribes una pregunta y tocas el mapa: cada territorio delibera, concluye y se pinta."};
function selInfo(){
  const el=$("#selinfo"); if(!el)return;
  if(!SEL.size){el.innerHTML=`<b>muestra:</b> toda Colombia (proporcional a población real) — toca el mapa para acotar`;return;}
  el.innerHTML=`<b>muestra:</b> `+[...SEL].map(c=>
    `<span class="chip">${esc(MARG[c]?.nombre||c)}<i data-c="${c}">×</i></span>`).join("")+
    `<button id="cleartodo" type="button">todo el país</button>`;
  el.querySelectorAll("i[data-c]").forEach(i=>i.onclick=()=>{SEL.delete(i.dataset.c);syncSel();});
  const b=el.querySelector("#cleartodo"); if(b)b.onclick=()=>{SEL.clear();syncSel();};
}
function syncSel(){
  if(SEL.size===1)cur=[...SEL][0];
  $("#dptosel").value=SEL.size===1?cur:"CO";
  paintNav();selInfo();render();
}

async function drawNav(){
  if(!GEO){try{GEO=await fetch("colombia.json").then(r=>r.json())}catch(e){return}}
  $("#navmap").innerHTML=`<svg viewBox="${GEO.viewBox}" role="img" aria-label="Mapa de Colombia">${
    Object.entries(GEO.paths).map(([c,p])=>`<path d="${p}" data-cod="${c}"/>`).join("")}</svg>`;
  const svg=$("#navmap svg");
  svg.addEventListener("click",e=>{
    const cod=e.target.dataset?.cod; if(!cod)return;
    if(MODO==="pais"&&PAIS.q){cur=cod;paintNav();render();mesa(cod);return;}
    if(SEL.has(cod)&&SEL.size>0)SEL.delete(cod);else SEL.add(cod);
    cur=cod; syncSel();
  });
  svg.addEventListener("mousemove",e=>{
    const cod=e.target.dataset?.cod;
    $("#maplabel").textContent=cod?
      (MARG[cod]?.nombre||cod)+(DECIDIDO[cod]?" · "+({a_favor:"a favor",en_contra:"en contra",depende:"dividido"})[DECIDIDO[cod]]:""):"—";
  });
  svg.addEventListener("mouseleave",()=>{$("#maplabel").textContent=MARG[cur]?.nombre||"—"});
  paintNav();
}
function paintNav(){
  document.querySelectorAll("#navmap path").forEach(p=>{
    const c=p.dataset.cod;
    p.classList.toggle("sel",SEL.has(c)||(MODO==="pais"&&c===cur));
    p.classList.remove("fav","con","dep");
    if(DECIDIDO[c])p.classList.add({a_favor:"fav",en_contra:"con",depende:"dep"}[DECIDIDO[c]]);
  });
  $("#maptag").textContent=MODO==="pais"?"el país responde":
    SEL.size?SEL.size+" elegido"+(SEL.size>1?"s":""):"toda colombia";
}
const AGEG=["0-4","5-9","10-14","15-19","20-24","25-29","30-34","35-39","40-44",
"45-49","50-54","55-59","60-64","65-69","70-74","75-79","80-84","85+"];

/* retrato pixel v2 procedural: peinado, tono, accesorio por oficio (determinista) */
function retrato(cv,seed,sexo,ocup){
  const S=16,ctx=cv.getContext("2d");cv.width=cv.height=S;
  let h=0;for(const c of seed)h=(h*31+c.charCodeAt(0))>>>0;
  const skin=["#f0c9a0","#e8b48c","#c98d5f","#a06b42","#8d5a3b","#6e4429"][h%6];
  const skin2=["#d9af83","#d19c72","#b07a4c","#8a5a36","#7a4b30","#5d3820"][h%6];
  const pelo=["#181818","#2e2013","#4a3018","#6b4423","#3d3d3d","#7a2e12"][(h>>3)%6];
  const ropa=["#5aa7ff","#59d97e","#ff9d47","#c792ea","#ff6fa5","#4dd6c1","#ffd23e","#e35d5d"][(h>>6)%8];
  const ropa2="#10141f";
  const F=(c,x,y,w,ht)=>{ctx.fillStyle=c;ctx.fillRect(x,y,w,ht)};
  ctx.clearRect(0,0,S,S);
  /* cabeza + sombreado */
  F(skin,5,3,6,6);F(skin2,10,4,1,5);
  /* peinados: 0 corto 1 alto 2 melena 3 recogido 4 calvo 5 crespo */
  const st=(h>>9)%6;
  F(pelo,5,2,6,2);
  if(st===1)F(pelo,5,1,6,2);
  if(st===2){F(pelo,4,3,1,6);F(pelo,11,3,1,6);}
  if(st===3){F(pelo,11,2,2,2);}
  if(st===4){ctx.clearRect(5,2,6,1);F(skin,5,2,6,1);F(pelo,5,2,1,1);F(pelo,10,2,1,1);}
  if(st===5){F(pelo,4,1,8,3);F(pelo,4,4,1,2);F(pelo,11,4,1,2);}
  if(sexo==="mujer"&&st!==4&&(h&2)){F(pelo,4,3,1,5);F(pelo,11,3,1,5);}
  /* cara */
  F("#10141f",6,5,1,1);F("#10141f",9,5,1,1);
  F(skin2,7,7,2,1);
  if((h>>12)%5===0)F("#8a3b2e",6,8,4,1);else F("#6e4429",7,8,2,1);
  /* cuerpo */
  F(ropa,4,9,8,5);F(ropa2,7,9,2,1);F(color(ropa,-25),4,12,8,2);
  F(skin,3,10,1,3);F(skin,12,10,1,3);
  /* accesorio por oficio */
  const o=(ocup||"").toLowerCase();
  if(/agricult|ganader|jornaler|campo|pescador|cafeter/.test(o)){ // sombrero vueltiao-ish
    F("#e8d9a0",4,2,8,1);F("#e8d9a0",3,3,2,1);F("#e8d9a0",11,3,2,1);F("#7a5c22",5,2,6,1);}
  else if(/conductor|mototaxi|domicili/.test(o)){F("#2f5faa",5,1,6,2);F("#2f5faa",4,2,2,1);} // gorra
  else if(/docente|profesor|universi|abogad|contador|médic|medic|enfermer/.test(o)){
    F("#dfe6f0",5,5,2,1);F("#dfe6f0",9,5,2,1);F("#dfe6f0",7,5,2,1);} // gafas
  else if(/comerciante|tender|vended/.test(o)){F("#c8483a",4,9,1,4);F("#c8483a",11,9,1,4);} // delantal
  else if(/miner|obra|construc|operari/.test(o)){F("#ffd23e",5,1,6,2);} // casco
  if(sexo==="mujer"&&(h>>15)%3===0){F("#ffd23e",4,7,1,1);F("#ffd23e",11,7,1,1);} // aretes
}
function color(hex,amt){
  const n=parseInt(hex.slice(1),16);
  const f=v=>Math.max(0,Math.min(255,v+amt));
  return "#"+((f(n>>16)<<16)|(f((n>>8)&255)<<8)|f(n&255)).toString(16).padStart(6,"0");
}

async function boot(){
  try{
    [RES,MARG,VAL]=await Promise.all([
      fetch("residents.json").then(r=>r.json()),
      fetch("marginals.json").then(r=>r.json()).then(m=>m.departamentos),
      fetch("validacion.json").then(r=>r.json()).catch(()=>({})),
    ]);
    DOS=await fetch("dossiers.json").then(r=>r.json()).catch(()=>({}));
  }catch(e){$("#censobody").textContent="corre el pipeline: generate_population.py";return;}
  const sel=$("#dptosel");
  sel.innerHTML=`<option value="CO">★ Toda Colombia (panel nacional)</option>`+
    Object.entries(MARG).sort((a,b)=>a[1].nombre.localeCompare(b[1].nombre))
    .map(([c,d])=>`<option value="${c}" ${c===cur?"selected":""}>${esc(d.nombre)}</option>`).join("");
  sel.onchange=e=>{const v=e.target.value;
    if(v==="CO")SEL.clear();else{SEL=new Set([v]);cur=v;}
    syncSel();$("#maplabel").textContent=MARG[cur]?.nombre||"—";};
  drawNav();selInfo();
  $("#modohelp").textContent=MODOTXT[MODO];
  $("#kpis").innerHTML=`<div><b>${RES.length.toLocaleString()}</b><span>residentes</span></div>
    <div><b>33</b><span>territorios</span></div>
    <div><b>${(VAL.bloques_provisionales||[]).length?"parcial":"completa"}</b><span>base DANE</span></div>`;
  render();
}

function natMarg(){
  const agg={nombre:"Colombia",edad:{},sexo:{hombre:0,mujer:0},poblacion:0,
    pib_sectores_pct:null,salud_pct:null,fuentes:{poblacion:"DANE proyecciones 2026, agregado nacional"}};
  for(const d of Object.values(MARG)){
    agg.poblacion+=d.poblacion||0;
    if(d.sexo){agg.sexo.hombre+=d.sexo.hombre;agg.sexo.mujer+=d.sexo.mujer;}
    if(d.edad)for(const[g,n]of Object.entries(d.edad))agg.edad[g]=(agg.edad[g]||0)+n;
  }
  return agg;
}
function render(){
  const nac=SEL.size===0;
  const d=nac?natMarg():MARG[cur];
  const mine=nac?RES:RES.filter(r=>r.dpto===cur);
  const dos=nac?{}:(DOS[cur]||{});
  /* censo */
  let h="";
  if(d.edad&&d.sexo){
    h+=`<h3>PIRÁMIDE — real (línea) vs sintética (barra)</h3><div class="pyr">`;
    const tot=mine.length;
    const rtotal=Object.values(d.edad).reduce((a,b)=>a+b,0);
    for(const g of [...AGEG].reverse()){
      const sh=mine.filter(r=>r.grupo_edad===g&&r.sexo==="hombre").length/tot*100;
      const sm=mine.filter(r=>r.grupo_edad===g&&r.sexo==="mujer").length/tot*100;
      const rr=(d.edad[g]||0)/rtotal*100;
      h+=`<div class="bar l"><i style="width:${sh*6}%"></i><s style="right:${rr/2*6}%"></s></div>
          <div class="lab">${g}</div>
          <div class="bar r"><i style="width:${sm*6}%"></i><s style="left:${rr/2*6}%"></s></div>`;
    }
    h+=`</div><div class="leyenda"><span><i style="background:var(--hom)"></i>hombres</span>
        <span><i style="background:var(--muj)"></i>mujeres</span>
        <span><i style="background:var(--text);width:2px"></i>censo real</span></div>`;
  } else {
    h+=`<h3>PIRÁMIDE</h3><div class="fuente">⚠ sexo/edad provisionales — a la espera del
        archivo de proyecciones DANE (el resto de bloques ya es real)</div>`;
  }
  const sal=d.salud_pct;
  if(sal){
    const got=mine.filter(r=>r.regimen_salud==="contributivo").length/mine.length*100;
    h+=`<h3>RÉGIMEN DE SALUD</h3>
    <div class="hbar"><div class="t"><span>contributivo real</span><b>${sal.contributivo}%</b></div>
      <div class="g"><i style="width:${sal.contributivo}%"></i></div></div>
    <div class="hbar"><div class="t"><span>contributivo sintético</span><b>${got.toFixed(0)}%</b></div>
      <div class="g"><i style="width:${got}%;background:var(--ok)"></i></div></div>
    <div class="fuente">${esc(d.fuentes?.salud||"")}</div>`;
  }
  const pib=d.pib_sectores_pct;
  if(pib){
    h+=`<h3>DE QUÉ VIVE (PIB por sector)</h3>`;
    for(const [s,p] of Object.entries(pib))
      h+=`<div class="hbar"><div class="t"><span>${esc(s.slice(0,38))}</span><b>${p}%</b></div>
          <div class="g"><i style="width:${Math.min(100,p*2)}%;background:var(--work)"></i></div></div>`;
    h+=`<div class="fuente">${esc(d.fuentes?.pib||"")}</div>`;
  }
  $("#censobody").innerHTML=h;
  /* ficha */
  if(nac){
    $("#dossier").innerHTML=`<b>Colombia entera en la mesa.</b><br><br>
      ${(d.poblacion/1e6).toFixed(1)} millones de personas proyectadas por el DANE
      para 2026, 33 territorios, 6.600 residentes sintéticos. En el panel nacional
      cada departamento entra a la muestra según su población REAL: pesa más un
      bogotano que un vaupense, como en el país de verdad.<br><br>
      <span class="tag" style="border-color:var(--ok)">muestreo proporcional DANE</span>
      <span class="tag" style="border-color:var(--ok)">33 voces regionales</span>`;
  } else
  $("#dossier").innerHTML= dos.vida_cotidiana?
    `<b>${esc(dos.apodo_gentilicio||d.nombre)}</b> · ${esc(dos.como_hablan||"")}<br><br>
     ${esc(dos.vida_cotidiana)}<br><br><i style="color:var(--faint)">${esc(dos.economia_vivida||"")}</i><br><br>
     ${(dos.orgullos||[]).map(o=>`<span class="tag" style="border-color:var(--ok)">${esc(o)}</span>`).join("")}
     ${(dos.dolores||[]).map(o=>`<span class="tag" style="border-color:var(--fail)">${esc(o)}</span>`).join("")}`
    :`<i style="color:var(--faint)">dossier en camino — lo está escribiendo el enjambre</i>`;
  const mu=$("#muestra");mu.innerHTML="";
  mine.slice(0,10).forEach(r=>{
    const div=document.createElement("div");div.className="res";
    const cv=document.createElement("canvas");retrato(cv,r.id,r.sexo,r.ocupacion);
    div.append(cv);div.insertAdjacentHTML("beforeend",
      `<span>${esc(r.nombre.split(" ")[0])}, ${r.edad} · ${esc(r.ocupacion)}</span>`);
    mu.append(div);
  });
  renderSugg();
}

/* ── LA CONVERSACIÓN: sondeo (paralelo) y tertulia (conversan entre ellos) ── */
let MODO="tertulia";
$("#modo").onclick=e=>{const m=e.target.dataset.m;if(!m)return;MODO=m;
  $("#modo").querySelectorAll("button").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.m===m)));
  $("#modohelp").textContent=MODOTXT[m];paintNav();};
const COLORES={a_favor:"var(--ok)",en_contra:"var(--fail)",depende:"var(--work)"};
const SUGG_BASE=["el nuevo metro / transporte público","que la IA haga su trabajo",
"el precio del café","irse a vivir a otra ciudad","que sus hijos estudien virtual"];
function renderSugg(){
  let temas;
  if(SEL.size!==1){
