        {role:"user",content:"TEMA: "+q+" (Colombia, septiembre 2026)"}]})});
    if(r.ok){const c=(await r.json()).content||"";
      CTX.txt=/SIN_NOVEDADES/.test(c)?null:c.trim();}
    /* Jev verifica el contexto antes de mostrarlo (fechas/consistencia) */
    if(CTX.txt){
      try{
        const v=await fetch("/api/opina",{method:"POST",headers:{"Content-Type":"application/json"},
          body:JSON.stringify({decide:true,
            state:"HOY: 21 septiembre 2026. Resumen noticioso a verificar:\n"+CTX.txt,
            questions:{fiable:{type:"noul",instructions:
              "Las viñetas son internamente consistentes, coherentes con la fecha de hoy (sin cargos o mandatos vencidos presentados como vigentes, sin fechas imposibles) y suenan a hechos citados, no a invención"}}})});
        if(v.ok)CTX.ok=(await v.json()).answers?.fiable?.noul>=0.5;
      }catch(e){}
    }
  }catch(e){}
  return CTX.txt;
}
function ctxBox(txt,host){
  const dudas=CTX.ok===false;
  (host||$("#resps")).insertAdjacentHTML("beforeend",
    txt?`<div class="ctx${dudas?" off":""}" style="${dudas?"border-color:var(--fail)":""}">
      <b style="${dudas?"color:var(--fail)":""}">${dudas?"⚠ CONTEXTO CON DUDAS (Jev no lo aprobó — tómenlo con pinzas)":"📰 CONTEXTO REAL (búsqueda verificada por Jev)"}</b>${esc(txt)}</div>`
       :`<div class="ctx off"><b>📰 SIN NOTICIAS FRESCAS</b>opinan desde su experiencia, no desde la prensa</div>`);
}
const ctxPara=txt=>(txt&&CTX.ok!==false)?`\nLO QUE DICEN LAS NOTICIAS HOY (hechos reales, reacciona a ESTO desde tu vida, puedes dudar de lo que leas):\n${txt}\n`:"";

let API_OK=null;  // ¿existe /api/opina? (en Vercel sí; en local http.server no)
async function flash(messages,max=170,temp=0.95){
  if(API_OK!==false){
    try{
      const r=await fetch("/api/opina",{method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({messages,max_tokens:max,temperature:temp})});
      if(r.ok){API_OK=true;return (await r.json()).content||"";}
      if(r.status===404||r.status===405)API_OK=false; else throw new Error("api "+r.status);
    }catch(e){if(API_OK)throw e;API_OK=false;}
  }
  // respaldo local: key del navegador (ajustes o local_keys)
  if(!cfg.orkey)throw new Error("sin backend ni key");
  const r=await fetch("https://openrouter.ai/api/v1/chat/completions",{
    method:"POST",headers:{Authorization:"Bearer "+cfg.orkey,"Content-Type":"application/json"},
    body:JSON.stringify({model:"deepseek/deepseek-v4.1-flash",max_tokens:max,
      temperature:temp,reasoning:{enabled:false},messages})});
  const j=await r.json();
  if(j.error)throw new Error(j.error.message||"api");
  return j.choices?.[0]?.message?.content||"";
}
function tallyVivo(postDe,n){
  const c={a_favor:0,en_contra:0,depende:0};
  Object.values(postDe).forEach(v=>c[v]++);
  const falta=n-Object.keys(postDe).length;
  $("#tally").innerHTML=
   `<div class="tal fav"><b>${c.a_favor}</b><span>a favor</span></div>
    <div class="tal con"><b>${c.en_contra}</b><span>en contra</span></div>
    <div class="tal dep"><b>${c.depende}</b><span>depende</span></div>`+
   (falta>0?`<div class="tal"><b>${falta}</b><span>por hablar</span></div>`:"");
}
function tally(p){
  $("#tally").innerHTML=
   `<div class="tal fav"><b>${p.a_favor}</b><span>a favor</span></div>
    <div class="tal con"><b>${p.en_contra}</b><span>en contra</span></div>
    <div class="tal dep"><b>${p.depende}</b><span>depende</span></div>`;
}
function muestraDe(sel,n){
  // muestra de los territorios elegidos (o todo el país), proporcional a población REAL
  const codigos=sel.size?[...sel]:Object.keys(MARG);
  const pesos=codigos.map(c=>[c,MARG[c]?.poblacion||1]);
  const tot=pesos.reduce((a,[,w])=>a+w,0);
  const out=[],usados=new Set();
  let guardia=0;
  while(out.length<n&&guardia++<n*200){
    let x=Math.random()*tot,cod=pesos[0][0];
    for(const [c,w] of pesos){x-=w;if(x<=0){cod=c;break}}
    const pool=RES.filter(r=>r.dpto===cod&&r.edad>=16&&!usados.has(r.id));
    if(pool.length){const r=pool[Math.floor(Math.random()*pool.length)];
      usados.add(r.id);out.push(r);}
  }
  return out;
}
